('TKT-20260423-B1C2D5', 13, 6, 4, 'Employee clicked on phishing link in email', 'Legal team member accidentally clicked a phishing link pretending to be a DocuSign notification. It redirected to a fake Microsoft login page. They did NOT enter credentials. Need security review.', 'High', 'Closed', '2026-04-23 14:00:00', '2026-04-23 15:00:00', '2026-04-24 08:00:00', '2026-04-23 10:00:00'),
('TKT-20260424-E4F5G8', 15, 7, 3, 'Large format plotter out of ink mid-print', 'HP DesignJet T630 ran out of cyan ink in the middle of a 30-page blueprint print job. Need replacement cartridges urgently. Job is for client delivery tomorrow.', 'High', 'Closed', '2026-04-24 18:00:00', '2026-04-24 16:00:00', '2026-04-25 08:00:00', '2026-04-24 10:00:00'),
('TKT-20260425-H7I8J1', 3, 8, 1, 'Timesheet system not calculating overtime correctly', 'The Kronos timesheet system is not calculating overtime hours for employees who work split shifts. Affecting 12 employees in the Operations department this pay period.', 'Critical', 'Resolved', '2026-04-25 14:00:00', '2026-04-26 10:00:00', NULL, '2026-04-25 10:00:00'),

