('TKT-20260501-K1L2M5', 6, 1, 2, 'Laptop touchpad not responding after Windows update', 'Touchpad on my Dell XPS 15 completely stopped working after yesterday Windows update. Using external mouse as workaround. Touchpad settings show "No precision touchpad found".', 'Medium', 'Assigned', '2026-05-02 10:00:00', NULL, NULL, '2026-05-01 10:00:00'),
('TKT-20260501-N4O5P8', 7, 2, NULL, 'Microsoft Project crashing when opening MPP files', 'MS Project 2024 crashes immediately when opening any .mpp file larger than 10MB. Smaller files work fine. Marketing project timeline is in a 15MB file.', 'High', 'Open', '2026-05-01 18:00:00', NULL, NULL, '2026-05-01 10:30:00'),
('TKT-20260501-Q7R8S1', 8, 3, 3, 'Conference room Webex Board not connecting to network', 'The Webex Board in Conference Room C is showing "No network connection" since this morning. Ethernet cable is plugged in. Other devices in the same room have internet.', 'High', 'In Progress', '2026-05-01 18:00:00', NULL, NULL, '2026-05-01 09:00:00'),
('TKT-20260501-T1U2V5', 9, 4, NULL, 'Contractor needs temporary access to project files', 'External contractor Mike Johnson from DesignCo needs read-only access to the Engineering SharePoint for 30 days. Project manager approved. NDA signed.', 'Low', 'Open', '2026-05-03 10:00:00', NULL, NULL, '2026-05-01 11:00:00'),
('TKT-20260501-W4X5Y8', 10, 5, 2, 'Outlook search not returning recent emails', 'Outlook search is not finding emails received in the last 2 weeks. Older emails appear in results. Rebuilt search index but problem persists.', 'Medium', 'In Progress', '2026-05-02 10:00:00', NULL, NULL, '2026-05-01 14:00:00'),
('TKT-20260501-Z7A8B1', 12, 6, 4, 'Company LinkedIn page compromised', 'Our company LinkedIn page posted unauthorized content this morning. The social media manager did not make these posts. Need to secure the account immediately.', 'Critical', 'Escalated', '2026-05-01 13:00:00', NULL, NULL, '2026-05-01 10:00:00'),
('TKT-20260502-C1D2E5', 13, 7, NULL, 'Printer toner low warning on all floors', 'All three floor printers (1st, 2nd, 3rd) are showing toner low warnings simultaneously. Procurement ordered replacement toners but need ETA from IT on installation.', 'Low', 'Open', '2026-05-03 10:00:00', NULL, NULL, '2026-05-02 08:00:00'),
('TKT-20260502-F4G5H8', 15, 8, 1, 'Database migration script failing on staging server', 'The Laravel migration script for the new procurement module is failing with foreign key constraint error on the staging environment. Production deployment blocked until resolved.', 'Critical', 'In Progress', '2026-05-02 12:00:00', NULL, NULL, '2026-05-02 08:30:00'),
('TKT-20260502-I7J8K1', 3, 1, NULL, 'Request for ergonomic keyboard for wrist pain', 'Experiencing wrist pain from typing. Occupational health recommended a Microsoft Sculpt Ergonomic Keyboard. Need IT to order and set up. Medical note attached.', 'Low', 'Open', '2026-05-04 10:00:00', NULL, NULL, '2026-05-02 09:00:00'),
('TKT-20260502-L1M2N5', 6, 3, 3, 'Branch office VPN tunnel down since last night', 'The site-to-site VPN between HQ and the Cebu branch office went down at approximately 11 PM last night. Branch office employees cannot access any HQ resources.', 'Critical', 'Escalated', '2026-05-02 12:00:00', NULL, NULL, '2026-05-02 07:00:00');

